Method.Implementation:
$$$TRACE("Entering IHC.ITF.ITFCOMMON.Operation.FileOperationWithDynamicPath")

set OriginalPath = pRequest.OriginalFilename
if OriginalPath["/" {
	Set lastSlash = $L(OriginalPath,"/")
	if lastSlash>1 {
		Set OriginalPath = $P(OriginalPath,"/",1,lastSlash-1)
	}	
	$$$TRACE("OriginalPath: " _ OriginalPath)
}
else {
	$$$TRACE("OriginalPath does not contain a /. OriginalPath: " _ OriginalPath)
}

set RelativePath = ""
if OriginalPath["SplitterInput" {
	set RelativePath = $P(OriginalPath,"SplitterInput",2,*)
}
else {
	$$$TRACE("SplitterInput folder was not found in source path and thus defulting to SplitterInput as the destination path")
}
Set RelativePath = "SplitterInput" _ RelativePath
$$$TRACE("RelativePath: " _ RelativePath)

set origFilePath = ..Adapter.FilePath
$$$TRACE("Adapter FilePath: " _ origFilePath)

set ..Adapter.FilePath = ..Adapter.FilePath _ RelativePath
$$$TRACE("Adapter FilePath updated to: " _ ..Adapter.FilePath)

set tSC=##super(pRequest,.pResponse)

set ..Adapter.FilePath = origFilePath
$$$TRACE("Adapter FilePath set back to orginal setting: " _ ..Adapter.FilePath)

Quit tSC
